import os

for root, dirs, files in os.walk(".codex/skills/docx"):
    depth = root.count(os.sep) - 2
    if depth > 3:
        continue
    for f in files:
        if f.endswith(".py") and depth <= 2:
            print(os.path.join(root, f))

